import { useCallback } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';

/**
 * 全站统一的「返回上一层」规则。
 *
 * 站内有几处"回上一层"的动作：场地页 ⇄ 设备页、设备页 → 资料页、漫游页 → 来路、
 * 地图上的父级地图。它们原先各自写死一个目标路径，于是出现两类毛病：
 * ① 明明是从上一页下钻进来的，返回键却把人送去另一个栏目（资料页一律回 `/archive`，
 *    从设备页的资料抽屉进来也一样，来路被丢掉）；
 * ② 两个页面互相跳时都用 push，历史越堆越长——场地 → 设备 → 场地 → 设备……返回键
 *    在两者之间打转，而且每一跳都多一条历史记录。
 *
 * 统一规则只有一句：**有来路就真返回，没来路才去兜底页**。
 * - `location.key === 'default'` 说明这是直接输网址 / 刷新进来的第一条历史，此时
 *   `navigate(-1)` 会把人送出站点，所以走 `fallback`，并用 `replace` 顶掉这条"没有来路"的历史。
 * - 其余情况一律 `navigate(-1)`：不新增历史，语义与浏览器返回键一致。
 */
export function useBackTo(fallback: string) {
  const navigate = useNavigate();
  const location = useLocation();
  return useCallback(() => {
    if (location.key === 'default') navigate(fallback, { replace: true });
    else navigate(-1);
  }, [fallback, location.key, navigate]);
}

/** 下钻时带上来路标记：`navigate(to, { state: backState('/site') })`。 */
export function backState(from: string) {
  return { from };
}

/**
 * 读来路标记：`useCameFrom('/site')`。
 *
 * 给"这枚返回键的目标取决于从哪进来"的页面用：设备页那枚「返回场地模型」从场地页下钻进来时
 * 应该退回那一步（`navigate(-1)`），从设备索引/深链进来时才显式去三维场地。
 */
export function useCameFrom(from: string) {
  const location = useLocation();
  return (location.state as { from?: unknown } | null)?.from === from;
}
