import { useCallback, useEffect, useState, type RefObject } from 'react';

/**
 * 全屏：进入 / 退出 / 状态同步。
 *
 * 为什么要有这个文件：两处「全屏查看」按钮原来都只调 `requestFullscreen()`，
 * **再点一次什么也不会发生**（浏览器已经在全屏里，再请求同一个元素是空操作），
 * 用户只能去按 Esc —— 现场反馈就是这个。
 *
 * 浏览器差异也一并收在这里：
 * - 标准 API 与 WebKit 前缀（Safari / iPadOS 上只有前缀版）；
 * - 退出要调 `document.exitFullscreen()`，**不是**元素上的方法；
 * - 用户按 Esc / 系统手势退出时，只能靠 `fullscreenchange` 事件知道，所以状态以事件为准。
 */

type FullscreenDocument = Document & {
  webkitFullscreenElement?: Element | null;
  webkitExitFullscreen?: () => Promise<void> | void;
  webkitFullscreenEnabled?: boolean;
};

type FullscreenTarget = HTMLElement & {
  webkitRequestFullscreen?: () => Promise<void> | void;
};

/** 当前处于全屏的元素（标准或 WebKit 前缀）。 */
export function fullscreenElement(): Element | null {
  if (typeof document === 'undefined') return null;
  const doc = document as FullscreenDocument;
  return doc.fullscreenElement ?? doc.webkitFullscreenElement ?? null;
}

/** 这个元素能不能全屏（iOS Safari 上普通元素没有这个能力，按钮就不该装作能用）。 */
export function canFullscreen(target: HTMLElement | null | undefined): boolean {
  if (!target) return false;
  const element = target as FullscreenTarget;
  return typeof element.requestFullscreen === 'function' || typeof element.webkitRequestFullscreen === 'function';
}

async function enterFullscreen(target: HTMLElement) {
  const element = target as FullscreenTarget;
  if (typeof element.requestFullscreen === 'function') return element.requestFullscreen();
  if (typeof element.webkitRequestFullscreen === 'function') return element.webkitRequestFullscreen();
}

async function leaveFullscreen() {
  const doc = document as FullscreenDocument;
  if (typeof doc.exitFullscreen === 'function') return doc.exitFullscreen();
  if (typeof doc.webkitExitFullscreen === 'function') return doc.webkitExitFullscreen();
}

/**
 * 把一个元素接上「全屏查看」按钮：`active` 表示**这个元素**正处在全屏（别人全屏时不算），
 * `toggle` 进去 / 出来；`supported` 为假时调用方应当不渲染按钮（别给死按钮）。
 */
export function useFullscreen(target: RefObject<HTMLElement | null>) {
  const [active, setActive] = useState(false);
  const [supported, setSupported] = useState(false);

  useEffect(() => {
    const sync = () => setActive(fullscreenElement() === target.current);
    sync();
    setSupported(canFullscreen(target.current));
    document.addEventListener('fullscreenchange', sync);
    document.addEventListener('webkitfullscreenchange', sync);
    // 目标元素是首帧之后才挂上的（舞台在加载态之后渲染），挂载后要补一次能力判断。
    const timer = window.setTimeout(() => setSupported(canFullscreen(target.current)), 0);
    return () => {
      window.clearTimeout(timer);
      document.removeEventListener('fullscreenchange', sync);
      document.removeEventListener('webkitfullscreenchange', sync);
    };
  }, [target]);

  const toggle = useCallback(() => {
    const element = target.current;
    if (!element) return;
    const inFullscreen = fullscreenElement() === element;
    // 退出/进入都可能被浏览器拒绝（例如没有用户手势、或元素被卸载），静默忽略即可：
    // 状态由 `fullscreenchange` 事件驱动，不会因为一次失败就显示错。
    const action = inFullscreen ? leaveFullscreen() : enterFullscreen(element);
    void Promise.resolve(action).catch(() => {});
  }, [target]);

  return { active, supported, toggle };
}
